/* Settlements, local happiness and population-conserving migration. */
const Civic=(()=>{
function settlement(cell){return cell.buildings.includes('city')?'City':cell.buildings.includes('village')?'Town':null;}
function upgrade(s){s.cells.forEach(cell=>{cell.improvements=cell.improvements||[];cell.migration=cell.migration||{incoming:0,outgoing:0};if(settlement(cell)&&!cell.settlement)cell.settlement=((s.countries[cell.country]?.name||'Independent')+' '+settlement(cell)+' '+cell.id).slice(0,60);});return s;}
function establish(s,imported){if(!imported)for(const c of s.countries){const owned=s.cells.filter(x=>x.land&&x.country===c.id),capital=owned.find(x=>x.buildings.includes('city'));if(!capital)continue;capital.settlement=c.name+' City';const towns=[];for(let i=0;i<Math.min(2,Math.floor(owned.length/8));i++){const cell=owned.filter(x=>!x.buildings.length).sort((a,b)=>{const distance=x=>Math.min(...[capital,...towns].map(t=>Math.hypot(x.point[0]-t.point[0],x.point[1]-t.point[1])));return distance(b)-distance(a)||a.id-b.id;})[0];if(cell){cell.buildings.push('village');cell.settlement=c.name+(i?' Grove':' Brook');towns.push(cell);}}}
// Move existing residents into established settlements; do not create free population.
for(const c of s.countries){const owned=s.cells.filter(x=>x.country===c.id&&x.land),centers=owned.filter(settlement);for(const town of centers){let need=Math.max(0,(settlement(town)==='City'?160:100)-town.population);for(const donor of owned.filter(x=>!settlement(x)).sort((a,b)=>a.id-b.id)){const count=Math.min(need,Math.max(0,donor.population-25));donor.population-=count;town.population+=count;need-=count;if(!need)break;}}}return upgrade(s);}
function capacity(cell){return (settlement(cell)==='City'?240:settlement(cell)?160:100)+(cell.improvements.includes('housing')?120:0);}
function happiness(s,cell){if(!cell.land||cell.country<0)return 0;const c=s.countries[cell.country];return Math.max(0,Math.min(100,c.morale+(settlement(cell)==='City'?10:settlement(cell)?6:0)+(cell.buildings.includes('school')?4:0)+(cell.improvements.includes('housing')?8:0)+(cell.improvements.includes('health')?6:0)-(cell.population>capacity(cell)?20:0)-(cell.occupation?20:0)-(c.lastShortage?15:0)-(s.regiments.some(r=>r.troops>0&&r.cell===cell.id&&Game.relation(s,r.country,cell.country)==='enemy')?15:0)));}
function migrate(s,notes){upgrade(s);const pop=s.cells.map(c=>c.population),happy=s.cells.map(c=>happiness(s,c)),room=s.cells.map(c=>Math.max(0,capacity(c)-c.population)),moves=[];s.cells.forEach(c=>c.migration={incoming:0,outgoing:0});for(const source of s.cells){if(!source.land||source.country<0||pop[source.id]<=25)continue;const dest=source.neighbors.map(id=>s.cells[id]).filter(c=>c.land&&c.country>=0&&!c.occupation&&room[c.id]>0&&happy[c.id]-happy[source.id]>=6&&Game.relation(s,source.country,c.country)!=='enemy').sort((a,b)=>happy[b.id]-happy[a.id]||a.id-b.id)[0];if(!dest)continue;const count=Math.min(pop[source.id]-25,Math.max(1,Math.floor(pop[source.id]*.04)),Math.max(1,Math.floor((happy[dest.id]-happy[source.id])/6)));moves.push({from:source.id,to:dest.id,count});}
// Reserve destination space from the starting snapshot, not from newly vacated homes.
for(const move of moves.sort((a,b)=>a.to-b.to||a.from-b.from)){const n=Math.min(move.count,room[move.to]);if(!n)continue;room[move.to]-=n;const a=s.cells[move.from],b=s.cells[move.to];a.population-=n;b.population+=n;a.migration.outgoing+=n;b.migration.incoming+=n;}
for(const c of s.countries){const owned=s.cells.filter(x=>x.country===c.id),incoming=owned.reduce((n,x)=>n+x.migration.incoming,0),outgoing=owned.reduce((n,x)=>n+x.migration.outgoing,0);c.migration={incoming,outgoing,net:incoming-outgoing};if(incoming||outgoing)notes.push(`${c.name}: population movement — ${incoming} arrivals, ${outgoing} departures (including moves within the country). People seek nearby happier places with room.`);}}
function rename(s,country,kind,id,name){if(s.phase!=='implement')throw Error('Rename during Implement, between turns.');if(typeof name!=='string'||!name.trim()||name.trim().length>60||/[\u0000-\u001f\u007f]/.test(name))throw Error('Use a name of 1–60 characters.');const item=kind==='settlement'?s.cells[id]:kind==='regiment'?s.regiments.find(r=>r.id===id):null;if(!item||item.country!==country||(kind==='settlement'&&!settlement(item)))throw Error('Choose one of your settlements or regiments.');item[kind==='settlement'?'settlement':'name']=name.trim();}
function validate(s){for(const cell of s.cells){if(!Array.isArray(cell.improvements)||new Set(cell.improvements).size!==cell.improvements.length||cell.improvements.some(k=>!Object.hasOwn(Research.applied,k))||!cell.migration||!['incoming','outgoing'].every(k=>Number.isInteger(cell.migration[k])&&cell.migration[k]>=0)||cell.settlement!==undefined&&(typeof cell.settlement!=='string'||cell.settlement.length>100))throw Error('Invalid settlement development.');}}
return {settlement,upgrade,establish,capacity,happiness,migrate,rename,validate};})();
